import{_ as s,a as t,b as i,c as n,d as a,e as r,f as o,g as l}from"./chunks/weather-heating-meteored.DOiN_qir.js";import{_ as u,o as d,c as p,a3 as c}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Météo et chauffage","description":"Installer et configurer le paquet optionnel de widgets graphiques.","frontmatter":{"title":"Météo et chauffage","description":"Installer et configurer le paquet optionnel de widgets graphiques."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/weather-heating.md","filePath":"fr/projects/grafik-visual-studio/weather-heating.md","lastUpdated":1793125707000}'),g={name:"fr/projects/grafik-visual-studio/weather-heating.md"};function h(m,e,k,f,v,E){return d(),p("div",null,[...e[0]||(e[0]=[c('<h1 id="wetter-und-heizung" tabindex="-1">Météo et chauffage <a class="header-anchor" href="#wetter-und-heizung" aria-label="Permalink to &quot;Météo et chauffage {#wetter-und-heizung}&quot;">​</a></h1><p>Les paquets et outils complémentaires sont proposés de manière centralisée sur <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a>. Ce site open source contient des descriptions et des instructions ; le téléchargement s&#39;effectue via le catalogue de paquets.</p><p><strong>Inspiré par les widgets « Météo et chauffage » pour ioBroker, créés par <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">rg-engineering</a>.</strong> Les widgets Studio constituent une implémentation spécifique pour Home Assistant.</p><p>À partir de <strong>Studio 0.1.194</strong>, vous pouvez installer le paquet <strong>« Météo et chauffage » 1.7.0</strong>. Il comprend : un <strong>graphique général</strong>, un <strong>graphique en barres sur deux semaines</strong>, un <strong>widget météo</strong>, une <strong>vue d&#39;ensemble des pièces chauffées</strong>, un <strong>widget météo METEORED</strong>, un <strong>suivi de l&#39;état des fenêtres</strong>, une fonction pour <strong>informer le propriétaire</strong> et les <strong>paramètres généraux de chauffage</strong>. La référence fonctionnelle est <a href="https://github.com/rg-engineering/ioBroker.vis-2-widgets-weather-and-heating" target="_blank" rel="noreferrer">ioBroker.vis-2-widgets-weather-and-heating</a> ; toutefois, Studio utilise ses propres modes de représentation. D&#39;autres widgets liés à la météo et au chauffage, ainsi que des intégrations spécifiques aux adaptateurs ioBroker, ne sont pas encore inclus.</p><h2 id="installieren" tabindex="-1">Installation <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installation {#installieren}&quot;">​</a></h2><p>Téléchargez <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=de" target="_blank" rel="noreferrer">ugso.weather-heating.wg</a>. Accédez à <strong>Paramètres → Packs de widgets → Installer un fichier .wg / .wg.zip local</strong> et sélectionnez le fichier. Après un rechargement, un nouvel ensemble apparaît, doté d&#39;une couleur attribuée automatiquement. L&#39;attribution de cette couleur est conservée dans le navigateur, même en cas de suppression et de réinstallation. Les 74 widgets intégrés restent disponibles.</p><h2 id="diagramm-konfigurieren" tabindex="-1">Configurer le diagramme <a class="header-anchor" href="#diagramm-konfigurieren" aria-label="Permalink to &quot;Configurer le diagramme {#diagramm-konfigurieren}&quot;">​</a></h2><p>Vous pouvez mettre à jour un pack installé (de 1.0.0 à 1.6.0) vers la version 1.7.0 en utilisant la même procédure d&#39;importation. Les widgets existants et les valeurs de projet sont conservés. Les mises à jour ne peuvent qu&#39;ajouter de nouveaux widgets ; toute modification des définitions existantes ou toute tentative de retour à une version antérieure (downgrade) sera rejetée.</p><h2 id="allgemeine-heizparameter" tabindex="-1">Paramètres généraux de chauffage <a class="header-anchor" href="#allgemeine-heizparameter" aria-label="Permalink to &quot;Paramètres généraux de chauffage {#allgemeine-heizparameter}&quot;">​</a></h2><p>Le widget affiche huit lignes : <strong>Période de chauffage active</strong>, <strong>Jour férié aujourd&#39;hui</strong>, <strong>Présent</strong>, <strong>Fête en cours</strong>, <strong>Invités présents</strong>, <strong>Vacances à domicile</strong>, <strong>Vacances (absent)</strong> et <strong>Mode cheminée</strong>. Dans la section <strong>Entités des paramètres de chauffage</strong>, vous pouvez associer une entité HA spécifique à chaque ligne. L&#39;entité « pièce » (choisie en option) s&#39;affiche sous forme de texte au-dessus des commutateurs ; elle n&#39;est pas modifiée. L&#39;instance <code>heatingcontrol.0</code> initiale n&#39;est pas requise.</p><p>En mode exécution (runtime), les entités <code>input_boolean.*</code> et <code>switch.*</code> disponibles peuvent être commutées (activées/désactivées) via l&#39;état <code>on</code>/<code>off</code>. Chaque action n&#39;agit que sur l&#39;entité cliquée. Les capteurs, comme <code>binary_sensor.*</code>, servent uniquement d&#39;affichage. Pendant l&#39;exécution d&#39;une commande, l&#39;entité concernée est verrouillée ; les erreurs sont signalées via l&#39;état de commutation existant dans Studio. L&#39;option <strong>Général → Lecture seule</strong> bloque toutes les actions de commutation. L&#39;option <strong>Sans carte</strong> supprime l&#39;arrière-plan de carte externe.</p><p>Les lignes non liées sont désactivées en mode exécution et marquées comme <strong>Non lié</strong>. Si des valeurs liées sont manquantes ou indisponibles, l&#39;état affiché est <strong>Inconnu</strong>, accompagné d&#39;un commutateur hachuré. Aucune valeur de prévisualisation n&#39;est utilisée comme valeur en temps réel. Les cases à cocher situées sous <strong>Prévisualisation</strong> ne s&#39;appliquent qu&#39;à l&#39;éditeur pour les éléments non liés ; aucune commande de commutation n&#39;y est envoyée non plus.</p><p>L&#39;ensemble des neuf liaisons d&#39;entités, valeurs de prévisualisation, paramètres de lecture seule et options d&#39;affichage sont conservés dans le projet ainsi que lors de l&#39;exportation du widget. Le widget regroupe vos entités HA (Home Assistant) existantes ; il ne calcule pas les durées de chauffage, les jours fériés ou la présence, et ne contient pas de système de régulation de chauffage propre.</p><p><img src="'+s+'" alt="Paramètres généraux de chauffage et leurs liaisons d&#39;entités"></p><h2 id="meinen-vermieter-informieren" tabindex="-1">Informer mon propriétaire <a class="header-anchor" href="#meinen-vermieter-informieren" aria-label="Permalink to &quot;Informer mon propriétaire {#meinen-vermieter-informieren}&quot;">​</a></h2><p>Le widget propose les champs <strong>Priorité</strong> (Information, Important, Urgent), <strong>Message</strong> et <strong>Envoyer</strong>. Dans l&#39;éditeur, il s&#39;agit d&#39;une prévisualisation. Lors de l&#39;exécution, les données ne sont transmises à Home Assistant que lorsqu&#39;une action d&#39;envoi est explicitement déclenchée. Les messages vides ainsi que les clics répétés survenant pendant une transmission en cours sont ignorés. En cas d&#39;erreur, le message est conservé pour une nouvelle tentative ; si Home Assistant (HA) l&#39;accepte, il est supprimé. L&#39;acceptation par HA ne confirme pas la bonne réception effective du message.</p><p>Sous la rubrique <strong>Général</strong>, vous trouverez les options suivantes : <strong>Sans carte</strong>, <strong>Type de message</strong>, <strong>Action de notification HA</strong>, <strong>Entité de notification</strong> et <strong>Objet / En-tête du message</strong>. Exemple : utilisez l&#39;action <code>notify.send_message</code> avec votre entité spécifique <code>notify.vermieter</code>. Vous pouvez également utiliser une action nommée préalablement configurée, telle que <code>notify.vermieter_email</code> ; dans ce cas, le champ « Entité » reste vide. L&#39;identifiant générique <code>notify.notify</code> n&#39;est pas accepté. Les destinataires, les identifiants d&#39;accès et les fournisseurs de services doivent être configurés dans Home Assistant, et non dans le widget. Consultez la section <a href="https://www.home-assistant.io/integrations/notify/" target="_blank" rel="noreferrer">Notifications HA</a>.</p><p>Les types de messages — e-mail, WhatsApp, Signal, Pushbullet et Jira — correspondent au canal configuré. Ce choix n&#39;installe aucun fournisseur de service et ne modifie pas automatiquement la destination dans Home Assistant. L&#39;instance ioBroker d&#39;origine, <code>email.0</code>, est remplacée par votre action Home Assistant. Dans la version initiale, seul l&#39;envoi par e-mail est implémenté ; toutefois, l&#39;interface Studio utilise la même configuration HA pour tous les canaux paramétrés.</p><p>Le titre et la priorité sont insérés sous forme de texte avant le message, par exemple <code>Meinen Vermieter informieren</code> et <code>[urgent]</code>. La priorité ne correspond pas à un niveau de distribution ou d&#39;alerte spécifique à un fournisseur. Limites : 10.000 caractères pour le message, 200 caractères pour le titre. Les brouillons sont conservés lors des mises à jour d&#39;état HA (Home Assistant), mais uniquement dans le formulaire actuel : un changement de page ou un rechargement les supprime. Les exportations de projets ou de widgets incluent la configuration, mais pas les messages saisis.</p><p><img src="'+t+`" alt="Formulaire de message et configuration de la cible HA dans l&#39;éditeur"></p><h2 id="fensterstatus-ubersicht" tabindex="-1">Aperçu de l&#39;état des fenêtres <a class="header-anchor" href="#fensterstatus-ubersicht" aria-label="Permalink to &quot;Aperçu de l&#39;état des fenêtres {#fensterstatus-ubersicht}&quot;">​</a></h2><p>Dans la section <strong>Liste des fenêtres</strong>, vous sélectionnez une entité HA et, éventuellement, un attribut contenant une liste JSON. Le point de données d&#39;origine se nomme <code>WindowStatesHtmlTableVis2</code>, mais il contient du JSON. En l&#39;absence de liaison avec une entité, le widget utilise l&#39;aperçu modifiable :</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wohnzimmer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;seit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 12:30&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;room&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Küche&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sinceText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;seit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;changed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;03.10.2026 11:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;isOpen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>isOpen</code> accepte les valeurs booléennes, 1/0, ainsi que les textes <code>true</code>/<code>false</code>, <code>on</code>/<code>off</code> et <code>open</code>/<code>closed</code>. Si l&#39;état est absent, le widget reconnaît les anciens noms d&#39;icônes <code>fts_window_1w_open.svg</code> et <code>fts_window_1w.svg</code>, sans pour autant charger de fichiers image. Sinon, la mention <strong>Inconnu</strong> s&#39;affiche. Les textes relatifs aux pièces et aux modifications sont affichés sous forme de texte brut, et non en HTML. Limites : 200.000 caractères JSON, 500 pièces et 512 caractères par champ de texte.</p><p><strong>Pièces ouvertes : Entité</strong> et un attribut optionnel fournissent un nombre entier non négatif. Sont comptées les pièces dont les fenêtres sont ouvertes. Sans cette liaison, le nombre est déduit uniquement à partir d&#39;une liste non vide contenant des états entièrement connus. En l&#39;absence de données liées, aucune prévisualisation n&#39;est utilisée ; un nombre inconnu est explicitement affiché.</p><p>Sous <strong>Couleurs</strong>, on trouve le titre, la ligne d&#39;état, le nom de la pièce (ouvert/fermé), l&#39;heure de la dernière modification (ouvert/fermé) et l&#39;arrière-plan de la pièce. Par défaut, l&#39;état « ouvert » utilise le rouge, l&#39;état « fermé » le vert, et l&#39;heure de modification associée le bleu. L&#39;affectation suit les noms des champs ; l&#39;inversion présente dans l&#39;original n&#39;est pas reprise. Une couleur d&#39;arrière-plan spécifique est utilisée, indépendante de la valeur de thème ioBroker <code>background.paper</code>. L&#39;option <strong>Général → Sans carte</strong> supprime l&#39;arrière-plan extérieur de la carte. Les paramètres sont conservés dans le projet ainsi que lors de l&#39;exportation du widget.</p><p>Votre entité HA doit déjà fournir la liste JSON ; le widget n&#39;agrège pas les capteurs de fenêtre individuels et ne modifie pas les états dans HA. Aucun adaptateur <code>heatingcontrol</code> n&#39;est requis.</p><p><img src="`+i+`" alt="Aperçu de l&#39;état des fenêtres avec les pièces ouvertes et fermées"></p><p>Sous <strong>Général</strong>, vous trouverez le titre, le nombre de séries (1–10), la légende et l&#39;option d&#39;affichage sans carte. La première série peut utiliser l&#39;entité générale. Chaque groupe <strong>Données [N]</strong> propose sa propre entité, un attribut optionnel, un JSON de prévisualisation, des clés X/Y, un nom, une unité, une couleur, un type (ligne/barre), un axe des valeurs (gauche/droite) et un calcul de différence. Avec une liaison à une entité, le graphique lit exclusivement son état ou son attribut. En l&#39;absence de données en temps réel, aucun JSON de prévisualisation n&#39;est utilisé. Aucune écriture d&#39;états dans HA (Home Assistant) n&#39;est effectuée.</p><p>Exemple de JSON de prévisualisation ou d&#39;attribut HA :</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T08:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T09:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T10:00:00&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Les clés par défaut sont <code>x</code> et <code>value</code> ; il est également possible d&#39;utiliser des clés personnalisées ainsi que des paires <code>[x,y]</code>. Le champ <strong>Temps</strong> attend des dates au format ISO ou des millisecondes Unix. Le champ <strong>Catégorie</strong> permet d&#39;afficher du texte, par exemple des années. Les points temporels sont triés avant le calcul des différences. Les valeurs manquantes interrompent la ligne et la séquence des différences ; la première différence n&#39;a pas de prédécesseur. Les axes gauche et droit sont mis à l&#39;échelle indépendamment.</p><p>L&#39;<strong>axe X</strong> utilise la clé standard <code>ddd HH:mm</code> pour les étiquettes. Jetons (tokens) pris en charge : <code>YYYY</code>, <code>MM</code>, <code>DD</code>, <code>ddd</code>, <code>HH</code>, <code>mm</code>, <code>ss</code>. Les couleurs sont définies sous <strong>WIDGET → CSS Graphique</strong>. Jusqu&#39;à 20.000 lignes de saisie sont acceptées ; Les séries volumineuses sont limitées à un maximum de 500 points par série. Le widget ne récupère pas l&#39;historique HA (Home Assistant) : l&#39;entité sélectionnée doit déjà fournir le tableau de données.</p><p><img src="`+n+'" alt="Ensemble installé avec aperçu du graphique"></p><h2 id="balkendiagramm-fur-zwei-wochen" tabindex="-1">Graphique en barres sur deux semaines <a class="header-anchor" href="#balkendiagramm-fur-zwei-wochen" aria-label="Permalink to &quot;Graphique en barres sur deux semaines {#balkendiagramm-fur-zwei-wochen}&quot;">​</a></h2><p>Les groupes <strong>Semaine actuelle</strong> et <strong>Semaine précédente</strong> contiennent chacun sept entités HA (du lundi au dimanche), ainsi que des valeurs de prévisualisation modifiables. Le widget compare les paires de jours côte à côte. Il ne calcule pas lui-même l&#39;historique hebdomadaire et ne décale pas les valeurs lors du passage à la semaine suivante : vos capteurs doivent fournir la valeur correspondant à chaque jour.</p><p>L&#39;option <strong>Afficher les valeurs hebdomadaires</strong> fonctionne de la même manière que l&#39;option originale « Visible » : si elle est désactivée, le widget affiche uniquement les valeurs de prévisualisation ; si elle est activée, il lit exclusivement les 14 entités journalières. Les valeurs « live » non liées, indisponibles ou non numériques ne génèrent pas de barres. Zéro est une valeur valide. La visibilité globale du widget se gère toujours via le paramètre <strong>Visibilité</strong>.</p><p>Dans la section <strong>Général</strong>, vous pouvez configurer le titre et sa couleur, la couleur du texte de la légende, l&#39;unité, les couleurs des semaines, la couleur des étiquettes des axes, le positionnement de l&#39;axe Y (gauche/droite), le nombre de décimales (0 à 5), la légende et l&#39;option <strong>Sans carte</strong>. L&#39;<strong>axe X</strong> dispose de sa propre couleur. Les unités et les valeurs formatées apparaissent dans la légende et dans les infobulles des barres ; les jours de la semaine s&#39;affichent dans la langue de l&#39;application. Les couleurs sont appliquées selon vos réglages.</p><p><img src="'+a+'" alt="Graphique en barres sur deux semaines dans l&#39;ensemble installé"></p><h2 id="wetter-widget" tabindex="-1">Widget météo <a class="header-anchor" href="#wetter-widget" aria-label="Permalink to &quot;Widget météo {#wetter-widget}&quot;">​</a></h2><p>La <strong>Source de données</strong> propose <code>home-assistant</code>, <code>json</code> et <code>individual</code>. La <strong>Structure des données</strong> permet de sélectionner cinq valeurs journalières (<code>daily</code>) ou jusqu&#39;à 24 valeurs horaires (<code>hourly</code>). Ces sources remplacent la sélection de l&#39;instance ioBroker et de l&#39;OID par des liaisons (bindings) vers HA (Home Assistant).</p><p>Avec <code>home-assistant</code>, vous sélectionnez une entité <code>weather.*</code>. Le serveur Studio récupère les prévisions via <a href="https://www.home-assistant.io/integrations/weather/" target="_blank" rel="noreferrer">weather.get_forecasts</a>. Les réponses valides sont mises en cache pendant cinq minutes ; en cas d&#39;erreur, une nouvelle tentative est effectuée après un délai minimal d&#39;une minute. L&#39;intégration météo utilisée doit prendre en charge le type de prévision choisi. Les unités de température et de précipitations sont extraites des attributs correspondants. Une véritable récupération des données depuis HA nécessite une connexion active à l&#39;add-on ou au Supervisor.</p><p>Avec <code>json</code>, le widget lit l&#39;<strong>attribut de prévision (JSON)</strong> sélectionné ; s&#39;il est vide, l&#39;état de l&#39;entité est utilisé. Un tableau (array) est attendu, par exemple :</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;datetime&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-03T12:00:00Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;temperature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;templow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cloud_coverage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;precipitation_probability&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Avec <code>individual</code>, vous associez les <strong>dates [1–5]</strong> ou les <strong>horaires [1–24]</strong>, ainsi que les valeurs correspondantes pour la température, les précipitations, la couverture nuageuse et la probabilité, à des capteurs individuels. Les données temporelles doivent être au format ISO ou exprimées en millisecondes Unix. Les vues journalières n&#39;utilisent que les cinq premières liaisons de chaque groupe de valeurs. Les moments non valides sont omis ; les valeurs manquantes interrompent les lignes. La valeur zéro est considérée comme valide. En l&#39;absence d&#39;entité météo ou JSON liée, les deux premières sources affichent des données de prévisualisation modifiables. Les données en temps réel manquantes ne sont jamais remplacées par des valeurs de prévisualisation.</p><p>Les paramètres <strong>Température</strong>, <strong>Pluie</strong>, <strong>Nuages</strong> et <strong>Probabilité de pluie</strong> peuvent être activés individuellement. Chaque groupe dispose de ses propres couleurs et d&#39;un axe des valeurs (gauche ou droite) ; les précipitations sont représentées sous forme de barres. L&#39;option <strong>Afficher dans le second graphique</strong> crée une zone graphique distincte. Si des unités différentes sont présentes sur un même axe, elles sont automatiquement séparées. L&#39;option <strong>Soleil ou nuages</strong> affiche la couverture nuageuse (ou son complément) en pourcentage ; elle n&#39;indique pas la durée d&#39;ensoleillement. Les valeurs manquantes fournies par la source ne sont pas estimées à partir de l&#39;état du temps. Il est possible de configurer le nom, l&#39;entité de localisation (optionnelle), la légende, les couleurs, le format de date sur l&#39;axe X, la taille, ainsi que l&#39;option <strong>Sans carte</strong>.</p><p><img src="'+r+'" alt="Widget météo affichant la température et les précipitations"></p><h2 id="ubersicht-uber-heizraume" tabindex="-1">Aperçu des chaufferies <a class="header-anchor" href="#ubersicht-uber-heizraume" aria-label="Permalink to &quot;Aperçu des chaufferies {#ubersicht-uber-heizraume}&quot;">​</a></h2><p>À partir de <strong>0.1.190</strong>, ce widget affiche un tableau de pièces au format HTML, généré à partir du point de données source <code>RoomStatesHtmlTable</code>. Dans la section <strong>Tableau de pièces</strong>, vous sélectionnez une entité HA (Home Assistant) et, éventuellement, un <strong>attribut de tableau</strong>. Si aucun attribut n&#39;est spécifié, c&#39;est l&#39;état (state) de l&#39;entité qui est utilisé. En cas de liaison, le widget exploite exclusivement cette valeur en temps réel ; si la valeur est absente ou indisponible, le message <strong>Aucun tableau de pièces disponible</strong> s&#39;affiche. En l&#39;absence de liaison avec une entité, le champ <strong>Aperçu du tableau de pièces (HTML)</strong> peut être modifié, y compris via l&#39;éditeur HTML.</p><p>Ce widget ne génère pas de données relatives aux pièces ni de profils de chauffage, et ne pilote aucun thermostat. Aucune instance ioBroker (telle que <code>heatingcontrol.0</code>) n&#39;est requise ; la source HA sélectionnée doit déjà fournir le tableau sous forme de chaîne HTML. Il est recommandé de placer les contenus HTML volumineux dans un attribut plutôt que dans l&#39;état (state).</p><p>Les options <strong>Général → Sans carte</strong>, <strong>Couleurs → Couleur des en-têtes</strong>, ainsi que les paramètres de taille et les réglages CSS communs sont disponibles. La structure des tableaux, la mise en forme du texte, les fusions de cellules (cell spans) ainsi que les couleurs et espacements définis sont conservés. Les scripts, gestionnaires d&#39;événements, formulaires, contenus intégrés (embeds) et ressources externes sont supprimés. La saisie est limitée à 200.000 caractères, et l&#39;affichage est restreint à 5.000 nœuds avec un maximum de 40 niveaux d&#39;imbrication. Les tableaux volumineux peuvent faire l&#39;objet d&#39;un défilement (scroll) à l&#39;intérieur du widget. Tous les paramètres sont préservés lors de l&#39;exportation du widget ou du projet.</p><p><img src="'+o+'" alt="Aperçu de la chaufferie avec tableau de prévisualisation"></p><h2 id="meteored-wetter-widget" tabindex="-1">Widget météo METEORED <a class="header-anchor" href="#meteored-wetter-widget" aria-label="Permalink to &quot;Widget météo METEORED {#meteored-wetter-widget}&quot;">​</a></h2><p>À partir de <strong>0.1.191</strong>, vous trouverez dans la section <strong>Général</strong> les options <strong>Sans carte</strong>, <strong>ID du widget Meteored</strong> et <strong>Activer le rechargement</strong>. Créez votre widget sur <a href="https://www.daswetter.com/widget/" target="_blank" rel="noreferrer">Meteored / daswetter.com</a> et saisissez uniquement son identifiant (ID) ; n&#39;entrez ni code HTML complet, ni URL. Sont autorisés : 1 à 128 caractères (lettres, chiffres, traits de soulignement ou traits d&#39;union). N&#39;oubliez pas d&#39;autoriser, sur le site du fournisseur, le nom de domaine depuis lequel vous accédez réellement à l&#39;interface d&#39;exécution (runtime).</p><p>L&#39;interface d&#39;exécution charge le chargeur officiel <code>https://api.meteored.com/widget/loader/ID</code> dans un cadre (frame) séparé. Un accès à Internet ainsi qu&#39;une configuration valide auprès du fournisseur sont requis. L&#39;option <strong>Activer le rechargement</strong> est activée par défaut et déclenche un rechargement une fois par heure. Si vous la désactivez, le minuteur s&#39;arrête ; toute modification ou suppression de l&#39;identifiant entraîne la suppression de l&#39;ancien minuteur. Le simple rafraîchissement de l&#39;interface d&#39;exécution ne relance pas le cadre ni son minuteur. Dans l&#39;éditeur, un aperçu de la configuration s&#39;affiche ; si l&#39;identifiant est vide ou invalide, aucun contenu n&#39;est chargé.</p><p>Le frame utilise <code>sandbox=&quot;allow-scripts&quot;</code> ; la page de chargement (<em>loader</em>) reçoit le même environnement isolé (<em>sandbox</em>) via son en-tête HTTP. Ainsi, le code Meteored s&#39;exécute sans accès au DOM du Studio. Le widget ne nécessite aucune entité HA et reprend le lieu, la langue et la mise en forme définis dans votre configuration Meteored. Ces trois options, ainsi que la taille et le CSS, sont conservées lors de l&#39;exportation. Une vérification complète de l&#39;affichage du fournisseur nécessite votre véritable identifiant de widget et un domaine autorisé.</p><p><img src="'+l+'" alt="Configuration METEORED dans l&#39;éditeur"></p><p>La construction reproductible du paquet et le manifeste vérifié sont disponibles dans le <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/weather-heating" target="_blank" rel="noreferrer">code source</a>. Le <a href="/fr/projects/grafik-visual-studio/widget-packages">contrat de paquet</a> décrit l&#39;interface 0.2.</p>',58)])])}const w=u(g,[["render",h]]);export{y as __pageData,w as default};
